def _rating_to_float(value, default: float = 0.50) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if number > 1.0:
        number = number / 100.0
    return max(0.0, min(0.99, number))


CUSTOM_PLAYER_FIELDS = (
    "three_tendency", "mid_tendency", "drive_tendency", "post_tendency", "dunk_tendency", "shot_tendency",
    "three_rating", "mid_rating", "rim_rating", "dunk_rating", "ft_rating",
    "usage", "playmaking", "ball_handle",
    "steal", "block", "oreb", "dreb", "foul_draw", "foul_rate",
    "perimeter_def", "interior_def", "clutchness", "speed", "shot_iq", "iso_tendency",
)


def serialize_custom_player(player: Player) -> Dict:
    return {
        "name": player.name,
        "position": player.position,
        "secondary_positions": list(getattr(player, "secondary_positions", ()) or ()),
        "height": int(getattr(player, "height", 0) or 0),
        "badges": list(getattr(player, "badges", ()) or ()),
        "archetype": getattr(player, "archetype", "") or "",
        "go_to_shot": getattr(player, "go_to_shot", "") or default_player_go_to_shot(player),
        **{field_name: _rating_to_int(getattr(player, field_name, 0.50)) for field_name in CUSTOM_PLAYER_FIELDS},
    }


def custom_player_from_record(record: Dict) -> Player | None:
    if not isinstance(record, dict):
        return None
    name = str(record.get("name", "")).strip()
    pos = str(record.get("position", "SF")).strip().upper()
    if not name or pos not in ("PG", "SG", "SF", "PF", "C"):
        return None
    badges = record.get("badges", ())
    if isinstance(badges, str):
        badges = [b.strip() for b in badges.split(",") if b.strip()]
    secondary = record.get("secondary_positions") or default_secondary_positions(pos)
    if isinstance(secondary, str):
        secondary = tuple(s.strip().upper() for s in secondary.split(",") if s.strip())
    else:
        secondary = tuple(str(s).strip().upper() for s in secondary if str(s).strip())
    try:
        height = int(float(record.get("height", default_player_height(name, pos))))
    except (TypeError, ValueError):
        height = default_player_height(name, pos)
    go_to_shot = str(record.get("go_to_shot", "") or "").strip()
    if go_to_shot not in GO_TO_SHOT_PACKS:
        go_to_shot = default_player_go_to_shot(name, pos)
    player = Player(
        name, pos,
        _rating_to_float(record.get("three_tendency", 35)),
        _rating_to_float(record.get("mid_tendency", 30)),
        _rating_to_float(record.get("drive_tendency", 25)),
        _rating_to_float(record.get("post_tendency", 10)),
        _rating_to_float(record.get("dunk_tendency", 10)),
        _rating_to_float(record.get("shot_tendency", 40)),
        _rating_to_float(record.get("three_rating", 75)),
        _rating_to_float(record.get("mid_rating", 75)),
        _rating_to_float(record.get("rim_rating", 75)),
        _rating_to_float(record.get("dunk_rating", 70)),
        _rating_to_float(record.get("ft_rating", 75)),
        _rating_to_float(record.get("usage", 20)),
        _rating_to_float(record.get("playmaking", 50)),
        _rating_to_float(record.get("ball_handle", 50)),
        _rating_to_float(record.get("steal", 50)),
        _rating_to_float(record.get("block", 45)),
        _rating_to_float(record.get("oreb", 45)),
        _rating_to_float(record.get("dreb", 55)),
        _rating_to_float(record.get("foul_draw", 40)),
        _rating_to_float(record.get("foul_rate", 40)),
        _rating_to_float(record.get("perimeter_def", 55)),
        _rating_to_float(record.get("interior_def", 55)),
        clutchness=_rating_to_float(record.get("clutchness", 50)),
        secondary_positions=secondary,
        badges=tuple(str(b).strip() for b in badges if str(b).strip()),
        height=height,
        speed=_rating_to_float(record.get("speed", 60)),
        shot_iq=_rating_to_float(record.get("shot_iq", 70)),
        iso_tendency=_rating_to_float(record.get("iso_tendency", 20)),
        archetype=str(record.get("archetype", "")).strip(),
        go_to_shot=go_to_shot,
    )
    if not player.archetype:
        player.archetype = infer_custom_player_archetype(player)
    player.source_team = "Custom Player"
    player.fantasy_base_name = player.name
    return player


def load_custom_fantasy_players() -> List[Player]:
    if not os.path.exists(CUSTOM_PLAYERS_PATH):
        return []
    try:
        with open(CUSTOM_PLAYERS_PATH, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
    except Exception:
        return []
    records = payload.get("players", payload) if isinstance(payload, dict) else payload
    players = []
    for record in records or []:
        player = custom_player_from_record(record)
        if player is not None:
            if not getattr(player, "badges", ()):
                try:
                    assign_player_badges(Team("Custom Player", [player]))
                except NameError:
                    pass
            players.append(player)
    return players


def save_custom_fantasy_players(players: List[Player]):
    payload = {"players": [serialize_custom_player(player) for player in players]}
    with open(CUSTOM_PLAYERS_PATH, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)


def infer_custom_player_archetype(player: Player) -> str:
    pos = str(getattr(player, "position", "SF") or "SF").upper()
    three = _rating_to_int(getattr(player, "three_rating", 0.50))
    mid = _rating_to_int(getattr(player, "mid_rating", 0.50))
    rim = _rating_to_int(getattr(player, "rim_rating", 0.50))
    dunk = _rating_to_int(getattr(player, "dunk_rating", 0.50))
    play = _rating_to_int(getattr(player, "playmaking", 0.50))
    handle = _rating_to_int(getattr(player, "ball_handle", 0.50))
    pdef = _rating_to_int(getattr(player, "perimeter_def", 0.50))
    idef = _rating_to_int(getattr(player, "interior_def", 0.50))
    reb = max(_rating_to_int(getattr(player, "oreb", 0.50)), _rating_to_int(getattr(player, "dreb", 0.50)))
    block = _rating_to_int(getattr(player, "block", 0.50))
    iso = _rating_to_int(getattr(player, "iso_tendency", 0.50))

    if pos in ("PG", "SG"):
        if play >= 86 and three >= 84:
            return "shot-making floor general"
        if play >= 88:
            return "floor general"
        if three >= 88 and iso >= 65:
            return "deep-range shot creator"
        if handle >= 86 and rim >= 82:
            return "slashing creator"
        if pdef >= 82:
            return "point-of-attack stopper"
        if three >= 84:
            return "movement shooter"
        return "combo guard"
    if pos == "SF":
        if pdef >= 84 and max(three, rim, mid) >= 82:
            return "two-way wing"
        if play >= 82:
            return "point forward"
        if three >= 86:
            return "scoring wing"
        if dunk >= 84 and rim >= 84:
            return "athletic slasher"
        return "versatile wing"
    if pos == "PF":
        if three >= 84 and idef >= 70:
            return "two-way stretch four"
        if rim >= 86 and idef >= 82:
            return "interior two-way force"
        if three >= 84:
            return "stretch four"
        if reb >= 82 and idef >= 78:
            return "glass-cleaning defender"
        return "frontcourt finisher"
    if idef >= 86 and block >= 82 and rim >= 82:
        return "paint anchor"
    if play >= 82:
        return "post playmaking hub"
    if three >= 82:
        return "stretch five"
    if reb >= 84:
        return "glass-cleaning big"
    return "rim-running center"


