def fantasy_team_factories(year_prefix: str = None) -> List:
    factories = []
    seen_team_names = set()

    for name, fn in sorted(globals().items()):
        if not name.startswith("make_") or name in {"make_2016_playoff_team", "make_knicks_2025"}:
            continue
        if not callable(fn):
            continue

        try:
            team = fn()
        except TypeError:
            continue
        except Exception:
            continue

        if not isinstance(team, Team) or team.name in seen_team_names:
            continue
        if year_prefix and not team.name.startswith(year_prefix):
            continue

        seen_team_names.add(team.name)
        factories.append(fn)

    return factories


def gui_team_factories() -> Dict[str, callable]:
    teams = {}
    for factory in fantasy_team_factories():
        try:
            team = factory()
        except Exception:
            continue
        if isinstance(team, Team):
            teams.setdefault(team.name, factory)
    return dict(sorted(teams.items()))

_FANTASY_POOL_CACHE: Dict = {}


def _fantasy_pool_signature():
    import os
    sig = []
    for path in ("custom_players.json", "custom_roster_swaps.json"):
        try:
            sig.append(os.path.getmtime(os.path.join(os.path.dirname(os.path.abspath(__file__)), path)))
        except OSError:
            sig.append(0.0)
    return tuple(sig)


def build_fantasy_player_pools(year_prefix: str = None, use_cache: bool = False) -> Dict[str, List[Tuple[Player, str]]]:
    """
    Building the pool instantiates every team in the sim, which is slow for the
    all-time pool. With use_cache=True it is reused until the custom player or
    roster swap files change; each caller gets its own copy of the pool lists
    (the player objects are shared, so only callers that never mutate drafted
    players should opt in).
    """
    if not use_cache:
        return _build_fantasy_player_pools_uncached(year_prefix)
    key = (year_prefix, _fantasy_pool_signature())
    cached = _FANTASY_POOL_CACHE.get(key)
    if cached is None:
        _FANTASY_POOL_CACHE.clear()
        cached = _build_fantasy_player_pools_uncached(year_prefix)
        _FANTASY_POOL_CACHE[key] = cached
    return {pos: list(items) for pos, items in cached.items()}


def _build_fantasy_player_pools_uncached(year_prefix: str = None) -> Dict[str, List[Tuple[Player, str]]]:
    """
    Fantasy draft pool across simulator teams.
    If the same player appears more than once, show him once on the board,
    then let the user choose which simulator version to draft.
    """
    versions_by_name: Dict[str, List[Player]] = {}

    for factory in fantasy_team_factories(year_prefix):
        team = factory()
        if is_olympic_team(team) or team.name in {"1992 USA Dream Team", "2008 USA Redeem Team"}:
            continue
        apply_star_clutchness(team)
        assign_player_badges(team)
        for p in team.roster:
            clone = fantasy_player_clone(p, team.name)
            versions_by_name.setdefault(p.name, []).append(clone)

    for custom_player in load_custom_fantasy_players():
        assign_player_badges(Team("Custom Player", [custom_player]))
        clone = fantasy_player_clone(custom_player, "Custom Player")
        versions_by_name.setdefault(clone.name, []).append(clone)

    pools: Dict[str, List[Tuple[Player, str]]] = {pos: [] for pos in ("PG", "SG", "SF", "PF", "C")}
    for versions in versions_by_name.values():
        versions.sort(key=fantasy_ovr, reverse=True)
        representative = versions[0]
        representative.fantasy_versions = versions
        pos = representative.position if representative.position in pools else "SF"
        ovr = fantasy_ovr(representative)
        version_note = f" | {len(versions)} versions" if len(versions) > 1 else ""
        desc = (
            f"{representative.source_team} - OVR {ovr}{version_note}"
        )
        pools[pos].append((representative, desc))

    for pos in pools:
        pools[pos].sort(key=lambda item: fantasy_ovr(item[0]), reverse=True)

    return pools


# ---------------------------------------------------------------------------
# 2016 teams: non-stretch bigs don't take mid-range jumpers.
# Most 2016 bigs carried a default ~0.60 mid tendency even with no jumper
# (Hollins, Capela, Biyombo, Adams...). Strip it from every C/PF without a real
# three-point game, except the bigs who genuinely shoot the mid-range.
# ---------------------------------------------------------------------------
REAL_MID_RANGE_BIGS_2016 = {
    "LaMarcus Aldridge", "David West", "Tim Duncan", "Zach Randolph", "Dirk Nowitzki",
    "Blake Griffin", "Al Jefferson", "Amar'e Stoudemire", "David Lee", "Marc Gasol",
    "Pau Gasol", "Kevin Garnett", "Chris Bosh",
}


def _is_non_stretch_big_2016(player) -> bool:
    if player.position not in ("C", "PF"):
        return False
    return not (player.three_rating >= 0.60 and player.three_tendency >= 0.15)


def _with_2016_big_mid_cleanup(factory):
    import functools

    @functools.wraps(factory)
    def wrapped(*args, **kwargs):
        team = factory(*args, **kwargs)
        if isinstance(team, Team):
            for p in team.roster:
                if _is_non_stretch_big_2016(p) and p.name not in REAL_MID_RANGE_BIGS_2016:
                    p.mid_tendency = 0.0
        return team

    return wrapped


for _name, _fn in list(globals().items()):
    if _name.startswith("make_") and _name.endswith("_2016") and callable(_fn):
        globals()[_name] = _with_2016_big_mid_cleanup(_fn)


